package com.lexorion.workforce.service;import static com.lexorion.workforce.api.ResourceDtos.*;import com.lexorion.workforce.api.*;import com.lexorion.workforce.domain.*;import com.lexorion.workforce.repository.EmployeeRepository;import com.lexorion.workforce.tenant.*;import java.util.List;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class SelfServiceService {private final WorkspaceScope scope;private final EmployeeRepository employees;public SelfServiceService(WorkspaceScope s,EmployeeRepository e){scope=s;employees=e;}
 @Transactional(readOnly=true)public EmployeeResponse me(){return EmployeeResponse.from(current());}
 @Transactional(readOnly=true)public TeamResponse team(){var c=scope.context();Employee manager=current();if(manager.getStatus()!=EmploymentStatus.ACTIVE)throw new WorkforceException(403,"Active manager employee mapping required");List<TeamEmployee> values=employees.findByWorkspaceIdAndReportingManagerPlatformUserIdOrderByCodeAsc(c.workspaceId(),c.userId()).stream().map(TeamEmployee::from).toList();return new TeamResponse(values);}
 @Transactional(readOnly=true)public EmployeeResponse permittedRead(String rawCode){var c=scope.context();String code=rawCode.trim().toUpperCase(java.util.Locale.ROOT);Employee value=switch(c.role()){case OWNER,ADMIN->employees.findByWorkspaceIdAndCode(c.workspaceId(),code).orElseThrow(EmployeeNotFoundException::new);case MEMBER->employees.findByWorkspaceIdAndCodeAndPlatformUserId(c.workspaceId(),code,c.userId()).orElseThrow(EmployeeNotFoundException::new);case MANAGER->{Employee manager=current();if(manager.getStatus()!=EmploymentStatus.ACTIVE)throw new EmployeeNotFoundException();yield employees.findByWorkspaceIdAndCodeAndReportingManagerPlatformUserId(c.workspaceId(),code,c.userId()).orElseThrow(EmployeeNotFoundException::new);}};return EmployeeResponse.from(value);}
 private Employee current(){var c=scope.context();return employees.findByWorkspaceIdAndPlatformUserId(c.workspaceId(),c.userId()).orElseThrow(()->new WorkforceException(403,"Authenticated user has no Workforce employee mapping"));}
}
